// Package gateway is a Go port of the llm-gateway safety rules (prompt-injection scoring
// and PII redaction) plus a per-key token bucket, used by the gateway-proxy binary.
//
// The rules mirror src/llm_gateway/injection.py and pii.py. testdata/parity.json is
// generated by the Python implementation, and the tests assert the same scores, block
// decisions, triggers, and redactions. Go's regexp engine (RE2) treats \b and \d as
// ASCII only, while Python's are Unicode aware; the two can differ on non-ASCII digits
// or word characters next to a match.
package gateway

import (
	"math"
	"regexp"
)

type rule struct {
	pattern *regexp.Regexp
	weight  float64
	name    string
}

var injectionRules = []rule{
	{regexp.MustCompile(`(?i)ignore (all |the )?(previous|prior|above) (instructions|prompts?)`), 1.0, "instruction_override"},
	{regexp.MustCompile(`(?i)disregard (all |the )?(previous|prior|above|your) `), 0.8, "disregard"},
	{regexp.MustCompile(`(?i)you are now\b`), 0.7, "role_reassignment"},
	{regexp.MustCompile(`(?i)\b(act as|pretend to be|roleplay as)\b.{0,40}\b(dan|developer mode|jailbreak)\b`), 1.0, "jailbreak_persona"},
	{regexp.MustCompile(`(?i)(repeat|print|reveal|show) (the )?(words |text )?(above|your (system )?prompt|previous instructions)`), 1.0, "prompt_extraction"},
	{regexp.MustCompile(`(?i)\bsystem prompt\b`), 0.5, "mentions_system_prompt"},
	{regexp.MustCompile(`(?i)\bdeveloper mode\b`), 0.6, "developer_mode"},
	{regexp.MustCompile(`(?i)do anything now\b`), 0.8, "dan"},
	{regexp.MustCompile(`(?i)without any (restrictions|filters|rules|guidelines)`), 0.7, "remove_guardrails"},
	{regexp.MustCompile(`(?i)\bBEGIN SYSTEM\b|\bEND SYSTEM\b|\[/?INST\]`), 0.6, "delimiter_injection"},
}

// DefaultThreshold is the score at or above which a request is blocked.
const DefaultThreshold = 0.8

// Injection is the injection risk of one input.
type Injection struct {
	Score    float64  `json:"score"`
	Blocked  bool     `json:"blocked"`
	Triggers []string `json:"triggers"`
}

// AssessInjection scores text against every rule; it is blocked at or above threshold.
func AssessInjection(text string, threshold float64) Injection {
	score := 0.0
	triggers := []string{}
	for _, r := range injectionRules {
		if r.pattern.MatchString(text) {
			score += r.weight
			triggers = append(triggers, r.name)
		}
	}
	return Injection{Score: math.Round(score*1000) / 1000, Blocked: score >= threshold, Triggers: triggers}
}

type piiRule struct {
	label   string
	pattern *regexp.Regexp
}

// Applied in order, each on the output of the previous one, as in the Python version.
var piiRules = []piiRule{
	{"EMAIL", regexp.MustCompile(`[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}`)},
	{"SSN", regexp.MustCompile(`\b\d{3}-\d{2}-\d{4}\b`)},
	{"CREDIT_CARD", regexp.MustCompile(`\b(?:\d[ -]?){13,16}\b`)},
	{"PHONE", regexp.MustCompile(`\b(?:\+?1[ -]?)?\(?\d{3}\)?[ -]?\d{3}[ -]?\d{4}\b`)},
	{"IP", regexp.MustCompile(`\b(?:\d{1,3}\.){3}\d{1,3}\b`)},
}

// Redaction is redacted text plus the number of replacements per PII type.
type Redaction struct {
	Text   string         `json:"text"`
	Counts map[string]int `json:"counts"`
}

// Redact replaces PII with typed placeholders such as [EMAIL].
func Redact(text string) Redaction {
	counts := map[string]int{}
	for _, r := range piiRules {
		if n := len(r.pattern.FindAllStringIndex(text, -1)); n > 0 {
			counts[r.label] += n
			text = r.pattern.ReplaceAllLiteralString(text, "["+r.label+"]")
		}
	}
	return Redaction{Text: text, Counts: counts}
}
